/* Equation-specific explanations; notation is never assumed to be universal. */
const Learning = (() => {
 const symbols = {
  F: ['F · force magnitude', 'The size of a force, measured in newtons (N). This is a nonnegative scalar, not a direction. In the component equations, combine it with the force’s angle to find signed components.'],
  Fvector: ['F · force vector', 'The bold F is the complete force: magnitude and direction. Its Cartesian components are measured in N. It differs from ordinary F, which is only the magnitude.'],
  A: ['A · Force A magnitude', 'The nonnegative size of Force A, in N. Its direction is α in the worked examples. In the parallelogram equation, A is one of the two magnitudes; φ supplies their relative direction.'],
  B: ['B · Force B magnitude', 'The nonnegative size of Force B, in N. Its direction is β in the worked examples. In the parallelogram equation, B is the second magnitude.'],
  R: ['R · resultant magnitude', 'The size of the net force after adding the force vectors. Measured in N and always nonnegative. A zero magnitude means there is no defined resultant direction.'],
  thetaForce: ['θ (theta) · force direction from +x', 'In Fₓ = F cos θ and Fᵧ = F sin θ, θ is the counterclockwise angle from the positive x axis to the force vector in the xy plane. It is not the angle between two forces. If a given angle starts at the y axis, convert it to this convention or identify the adjacent and opposite components from the diagram.'],
  thetaResult: ['θ (theta) · resultant direction from +x', 'Here θ is the counterclockwise angle from the positive x axis to the resultant R. Use the signs of Rₓ and Rᵧ to select its quadrant. This is the resultant’s angle, not necessarily α, β, or the included angle φ.'],
  alpha: ['α (alpha) · Force A direction', 'In this lesson, α is the counterclockwise angle from +x to Force A in the xy plane. Use cos α for Aₓ and sin α for Aᵧ. In other engineering equations α can mean something else, including a 3D coordinate direction angle; check that equation’s definition.'],
  beta: ['β (beta) · Force B direction', 'In this lesson, β is the counterclockwise angle from +x to Force B in the xy plane. Use cos β for Bₓ and sin β for Bᵧ. It is not an angle from the y axis here.'],
  phi: ['φ (phi) · included angle between forces', 'For the parallelogram law, φ is the smaller angle (0–180°) between A and B when their tails share an origin. It is not measured from the x axis. If A points at 30° and B at 120°, φ = 90°. The interior angle in the head-to-tail triangle is 180° − φ, which explains why the law-of-cosines sign looks different.'],
  rvector: ['r · displacement vector', 'A directed displacement, in metres. For a force along A→B, r = rB − rA: subtract the starting point coordinates from the ending point coordinates. Choose the order to match the force direction.'],
  rmag: ['|r| · displacement magnitude', 'The length of the displacement vector, in metres: √(rₓ² + rᵧ² + r_z²). It must be greater than zero to form a unit vector. Dividing r by this length removes the units.'],
  uvector: ['u · unit direction vector', 'A dimensionless vector of magnitude 1. It specifies direction only. Multiply it by the force magnitude F (N) to produce the force vector in N.'],
  i: ['i · x-axis unit vector', 'A dimensionless vector of length 1 pointing along +x. Fₓi places the signed x component into the force vector.'],
  j: ['j · y-axis unit vector', 'A dimensionless vector of length 1 pointing along +y. Fᵧj places the signed y component into the force vector.'],
  k: ['k · z-axis unit vector', 'A dimensionless vector of length 1 pointing along +z. F_zk places the signed z component into the force vector.'],
  atan2: ['atan2 · quadrant-aware direction', 'atan2(y, x) uses both component signs to return the angle of the vector. The lab displays it as 0–360°. A TI-84-style inverse tangent of y/x needs a quadrant correction and cannot directly divide by x when x = 0.'],
  cos: ['cos · adjacent-component factor', 'For an angle measured from +x, F cos θ is the signed x component. Cosine is negative when the force points to the left. Set the calculator to the angle units used by the problem.'],
  sin: ['sin · opposite-component factor', 'For an angle measured from +x, F sin θ is the signed y component. Sine is negative when the force points downward. Set the calculator to the angle units used by the problem.']
 };
 for (const force of ['F','A','B','R']) for (const axis of ['x','y','z']) symbols[force+'_'+axis] = [`${force}${{x:'ₓ',y:'ᵧ',z:'_z'}[axis]} · signed ${axis} component`, `The part of ${force==='R'?'the resultant':'Force '+force} along the ${axis} axis, measured in N. Positive points along +${axis}; negative points along −${axis}. This is a signed scalar component, not the total magnitude. ${force==='R'?'Add all forces’ signed '+axis+' components to get this value.':'Use this component with the matching axis unit vector to construct the force vector.'}`];
 Object.assign(symbols,{
  cos3D:['cos · coordinate direction cosine','In these 3D equations, cosine of the angle with a positive axis equals the corresponding unit-vector component. Thus cos α = ux, cos β = uy, and cos γ = uz. This describes angles with all three axes, rather than a single planar orientation.'],
  positionA:['rA · position of point A','A vector from the coordinate origin O to point A, in metres. Its components are A’s x, y, and z coordinates. It is a point’s position, rather than the displacement from A to B.'],
  positionB:['rB · position of point B','A vector from the coordinate origin O to point B, in metres. Subtract rA from rB to get the displacement directed from A to B.'],
  displacement:['rAB · displacement from A to B','The vector pointing from point A to point B, measured in metres: rAB = rB − rA. Each component is ending coordinate minus starting coordinate. It is not a force and its magnitude is the distance between the points.'],
  displacementBA:['rBA · displacement from B to A','The vector pointing from B to A, in metres: rBA = rA − rB = −rAB. Reversing the endpoints changes every component’s sign but keeps the length unchanged.'],
  unitAB:['uAB · unit direction from A to B','The displacement rAB divided by its length |rAB|. It points from A to B, has magnitude 1, and is dimensionless. For a cable pulling at A toward B, this is the force direction.'],
  unitBA:['uBA · unit direction from B to A','The dimensionless unit vector from B to A. It equals −uAB. For a cable pulling at B toward A, use this direction instead of uAB.'],
  lengthAB:['|rAB| · distance between the points','The positive distance √((xB−xA)² + (yB−yA)² + (zB−zA)²), measured in metres. It is the same in either direction. Coincident points have zero distance, so their direction and unit vector are undefined.'],
  alpha3D:['α (alpha) · 3D angle with +x','In this coordinate-direction equation, α is the angle between the 3D displacement vector and the positive x axis, from 0° to 180°. cos α = ux. Unlike α in the 2D Force A example, this is not a counterclockwise planar orientation. A negative x component gives α > 90°.'],
  beta3D:['β (beta) · 3D angle with +y','Here β is the angle between the 3D displacement vector and the positive y axis, from 0° to 180°. cos β = uy. This differs from β in the Force B example, where it is measured counterclockwise from +x.'],
  gamma3D:['γ (gamma) · 3D angle with +z','Here γ is the angle between the displacement vector and the positive z axis, from 0° to 180°. cos γ = uz. A vector in the xy plane has uz = 0 and γ = 90°. These three direction angles satisfy cos²α + cos²β + cos²γ = 1.']
 });
 for(const axis of ['x','y','z']){
  symbols['r_'+axis]=[`${axis} displacement component`, `The ending ${axis} coordinate minus the starting ${axis} coordinate, measured in metres. A negative value means the displacement points toward −${axis}.`];
  symbols['u_'+axis]=[`${axis} unit-vector component`, `The signed ${axis} displacement divided by the point-to-point distance. It is dimensionless and lies between −1 and 1. It is also the cosine of the coordinate direction angle with +${axis}.`];
  for(const point of ['A','B'])symbols[axis+point]=[`${axis}${point} · ${point}’s ${axis} coordinate`, `The signed ${axis} coordinate of point ${point}, in metres, relative to the common origin. Use ending minus starting coordinates to find a displacement component.`];
 }
 const cards = [
  {title:'Find a position or displacement vector',body:'position',use:'Turn <strong>two points into a directed displacement</strong> from A to B. If A is the origin, this is B’s position vector.',need:'The <strong>x, y, z coordinates of A and B</strong> relative to the <strong>same origin</strong>.',condition:'Use <strong>the same length units</strong> for both points. Subtract <strong>end minus start</strong>: B − A for A→B. Zero displacement is valid, but cannot define a direction.',example:'A = <strong>(1, 1, 0) m</strong> and B = <strong>(4, 5, 0) m</strong> give rAB = <strong>(3, 4, 0) m</strong>.',symbols:['positionA','positionB','displacement','xA','xB']},
  {title:'Resolve a force into components',body:'components',use:'Find <strong>how much of a force acts along x and y</strong>. Start here when a 2D force is given by its magnitude and direction.',need:'The <strong>force magnitude F (N)</strong> and its <strong>angle θ from +x</strong>.',condition:'The force lies in the <strong>xy plane</strong>, and θ follows the stated counterclockwise convention. An angle from another axis must be converted or interpreted from the diagram.',example:'A <strong>100 N</strong> force at <strong>30° from +x</strong> has Fₓ ≈ <strong>86.60 N</strong> and Fᵧ = <strong>50 N</strong>.',symbols:['F','F_x','F_y','thetaForce']},
  {title:'Write a Cartesian force vector',body:'cartesian',use:'Represent <strong>magnitude and direction together</strong> in a form suitable for adding forces, projections, and cross products.',need:'The <strong>signed components Fₓ, Fᵧ, F_z</strong> in a common coordinate system. Obtain them from angles or a unit vector first.',condition:'Use <strong>mutually perpendicular Cartesian axes</strong> and consistent force units. For a 2D xy problem, <strong>F_z = 0</strong>.',example:'With Fₓ = <strong>80 N</strong>, Fᵧ = <strong>−60 N</strong>, and F_z = <strong>0</strong>, the force points right and down; its magnitude is <strong>100 N</strong>.',symbols:['Fvector','F_x','F_y','F_z','i','j','k']},
  {title:'Add forces by components',body:'sum',use:'Find the <strong>net force</strong> from two forces, or repeat the component sum for any number of forces.',need:'The <strong>signed x, y, and z components of every force</strong>.',condition:'All components must use the <strong>same axes and units</strong>. For concurrent forces this gives the resultant through their common point. For forces applied at different points on a rigid body, <strong>moments must also be considered</strong> to describe their full effect.',example:'If Aₓ = <strong>100 N</strong> and Bₓ = <strong>−40 N</strong>, then Rₓ = <strong>60 N</strong>; do not discard the minus sign.',symbols:['A_x','B_x','R_x','A_y','B_y','R_y']},
  {title:'Find resultant magnitude',body:'magnitude',use:'Turn the <strong>resultant’s signed components into its total size</strong>.',need:'The <strong>resultant components Rₓ, Rᵧ, R_z (N)</strong>, after summing forces.',condition:'The axes must be <strong>perpendicular</strong>. Use <strong>R_z = 0</strong> in a 2D problem. This gives magnitude only; it does not give direction.',example:'Rₓ = <strong>3 N</strong> and Rᵧ = <strong>4 N</strong> give R = <strong>5 N</strong>.',symbols:['R','R_x','R_y','R_z']},
  {title:'Find the 2D resultant direction',body:'direction',use:'Find <strong>which way the resultant points</strong>, measured from +x.',need:'The <strong>signed components Rₓ and Rᵧ</strong>.',condition:'The resultant must be <strong>nonzero</strong> and in the xy plane. atan2 handles all quadrants. Using tan⁻¹(Rᵧ/Rₓ) instead requires <strong>quadrant correction</strong>; when Rₓ = 0, use the y-component sign to choose 90° or 270°.',example:'Rₓ = <strong>−3 N</strong> and Rᵧ = <strong>4 N</strong> give θ ≈ <strong>126.87°</strong>, in quadrant II.',symbols:['thetaResult','R_x','R_y','atan2']},
  {title:'Use the parallelogram law',body:'parallelogram',use:'Find the <strong>resultant magnitude of two forces</strong> directly from their relative geometry.',need:'The <strong>two magnitudes A and B (N)</strong> and the <strong>included angle φ between them</strong>.',condition:'Use the <strong>tail-to-tail included angle</strong>. This form uses <strong>+2AB cos φ</strong>. It does not determine orientation relative to +x unless that orientation is also known.',example:'A = <strong>100 N</strong>, B = <strong>100 N</strong>, and φ = <strong>90°</strong> give R ≈ <strong>141.42 N</strong>.',symbols:['A','B','R','phi']},
  {title:'Build a unit vector from geometry',body:'unit',use:'Find a <strong>direction from two points</strong>, such as the direction of a cable.',need:'The <strong>coordinates of the starting and ending points</strong>, using the same length units. Form r = rB − rA first.',condition:'The points must be <strong>distinct</strong>: |r| &gt; 0. Choose the subtraction order to follow the required direction. The resulting u is <strong>dimensionless</strong>.',example:'A displacement of <strong>(3, 4, 0) m</strong> has length <strong>5 m</strong> and unit direction <strong>(0.6, 0.8, 0)</strong>.',symbols:['rvector','rmag','uvector']},
  {title:'Turn magnitude and direction into a force vector',body:'directed',use:'Express a force in Cartesian form when its <strong>magnitude and line of action are known</strong>.',need:'The <strong>force magnitude F (N)</strong> and a <strong>unit vector u pointing in the force’s direction</strong>.',condition:'Check that <strong>|u| = 1</strong>. A cable pulling at A toward B uses the A→B direction. Reversing the direction reverses every force component.',example:'F = <strong>100 N</strong> and u = <strong>(0.6, 0.8, 0)</strong> give force components <strong>(60, 80, 0) N</strong>.',symbols:['F','Fvector','uvector']},
  {title:'Find 3D coordinate direction angles',body:'direction3D',use:'Describe <strong>a vector’s orientation relative to each positive axis</strong>.',need:'The <strong>unit-vector components ux, uy, uz</strong>, or a nonzero vector’s components divided by its magnitude.',condition:'Each angle lies between <strong>0° and 180°</strong>. Here α is from <strong>+x</strong>, β from <strong>+y</strong>, and γ from <strong>+z</strong>. They are not the 2D counterclockwise angles used in the force lab.',example:'u = <strong>(0.6, 0.8, 0)</strong> gives α ≈ <strong>53.13°</strong>, β ≈ <strong>36.87°</strong>, and γ = <strong>90°</strong>.',symbols:['alpha3D','beta3D','gamma3D','u_x','u_y','u_z']}
 ];
 return {symbols,cards};
})();
